17	// statusCounts tallies an epic's picks by raw bd status (weft-6xi step 2/5).
18	// Ready is deliberately NOT surfaced as a fifth count: doing so would need an
19	// extra `bd ready --parent <epic>` subprocess call per epic on the whole-warp
20	// path (O(epics) extra calls), and the four raw statuses already let a caller
21	// derive readiness from `bd ready` directly when needed. Keeping status to
22	// bd's own four statuses also keeps every count reproducible from a single
23	// `bd list` call, which is what makes the tally below pure and unit-testable.
24	type statusCounts struct {
25		Closed     int `json:"closed"`
26		InProgress int `json:"in_progress"`
27		Blocked    int `json:"blocked"`
28		Open       int `json:"open"`
29	}
30	
31	// done is closed picks; remaining is everything not yet closed.
32	func (c statusCounts) done() int      { return c.Closed }
33	func (c statusCounts) remaining() int { return c.InProgress + c.Open + c.Blocked }
34	
35	func (c *statusCounts) add(o statusCounts) {
36		c.Closed += o.Closed
37		c.InProgress += o.InProgress
38		c.Blocked += o.Blocked
39		c.Open += o.Open
40	}
