42	// countByStatus is a pure, subprocess-free counting helper (the TDD core):
43	// given an epic's already-parsed picks, tally them by raw bd status. A status
44	// value outside open/in_progress/blocked/closed (bd's vocabulary may grow) is
45	// silently skipped — status is a live readout, not a validator, so an
46	// unrecognised status must not crash or skew the counts it does understand.
47	func countByStatus(children []warpChild) statusCounts {
48		var c statusCounts
49		for _, ch := range children {
50			switch ch.Status {
51			case "closed":
52				c.Closed++
53			case "in_progress":
54				c.InProgress++
55			case "blocked":
56				c.Blocked++
57			case "open":
58				c.Open++
59			}
60		}
61		return c
