218			es.ID, es.Title, es.Counts.Closed, es.Counts.InProgress, es.Counts.Blocked, es.Counts.Open, es.Done, es.Remaining)
219		for _, status := range []string{"closed", "in_progress", "blocked", "open"} {
220			group := make([]warpChild, 0, len(children))
221			for _, ch := range children {
