42	def _clean(text: object, limit: int = _TITLE_LIMIT) -> str:
43	    """Flatten a bd-supplied string for safe single-line interpolation: drop
44	    non-printable chars (newlines included), collapse whitespace, bound length."""
45	    flattened = "".join(ch if ch.isprintable() else " " for ch in str(text))
46	    collapsed = " ".join(flattened.split())
47	    if len(collapsed) > limit:
