69	    """Coerce ``bd epic status --json`` into clean ``{id,title,status,closed,
70	    total}`` dicts, dropping any record too malformed to render. Defensive by
71	    design: a bd version skew or locked-DB error payload must degrade, never
72	    raise (the hook's always-exit-0 contract)."""
73	    out: list[dict] = []
74	    if not isinstance(epic_status, list):
75	        return out
76	    for rec in epic_status:
77	        if not isinstance(rec, dict):
78	            continue
79	        epic = rec.get("epic")
80	        if not isinstance(epic, dict):
81	            continue
82	        eid = epic.get("id")
83	        if not eid:
84	            continue
85	        try:
86	            total = int(rec.get("total_children", 0))
87	            closed = int(rec.get("closed_children", 0))
88	        except (TypeError, ValueError):
89	            continue
90	        out.append(
91	            {
92	                "id": eid,
93	                "title": epic.get("title") or "",
94	                "status": epic.get("status"),
95	                "closed": closed,
96	                "total": total,
97	            }
98	        )
99	    return out
100	
101	
102	def active_epics(epic_status: object) -> list[dict]:
103	    """Normalized open epics with outstanding children, most-remaining first (a
104	    stable proxy for 'where the work is'). Returns ``_normalize_epics`` dicts."""
105	    out = [
106	        e
107	        for e in _normalize_epics(epic_status)
108	        if e["status"] == "open" and e["closed"] < e["total"]
109	    ]
110	    out.sort(key=lambda e: (-(e["total"] - e["closed"]), e["id"]))
111	    return out
112	
