114	def format_warp_status(
115	    ready_count: int | None,
116	    epic_status: object,
117	    *,
118	    max_epics: int = 5,
119	) -> list[str]:
120	    """Build the dynamic warp-status lines from parsed bd output.
121	
122	    ``ready_count is None`` means bd was unavailable; the numeric line is
123	    omitted so the hook degrades to orientation-only rather than lying.
124	    """
125	    lines: list[str] = []
126	    if ready_count is not None:
127	        noun = "pick" if ready_count == 1 else "picks"
128	        lines.append(f"Warp status: {ready_count} {noun} ready.")
129	
130	    epics = active_epics(epic_status)
131	    if epics:
132	        lines.append("Active epics (open, incomplete):")
133	        for e in epics[:max_epics]:
134	            pct = round(e["closed"] / e["total"] * 100) if e["total"] else 0
135	            # Both id and title are bd-supplied (untrusted warp) — clean both
136	            # before they enter the model's additionalContext.
137	            eid = _clean(e["id"])
138	            title = _clean(e["title"])
139	            lines.append(f"  {eid}  {title}  ({e['closed']}/{e['total']}, {pct}%)")
140	        extra = len(epics) - max_epics
141	        if extra > 0:
142	            lines.append(f"  …and {extra} more open epics.")
143	    return lines
144	
145	
146	def build_context(warp_lines: list[str]) -> str:
147	    """Assemble the SessionStart additionalContext: fixed orientation plus any
148	    dynamic warp-status lines."""
149	    parts = [ORIENTATION]
150	    if warp_lines:
151	        parts.append("\n".join(warp_lines))
152	    return "\n\n".join(parts)
